<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';
require_once __DIR__.'/../../config/db.php';
require_once __DIR__.'/../../includes/report_tools.php';
requireModuleAccess('finance');
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$asAt=$_GET['as_at']??$to;
$valid='/^\d{4}-\d{2}-\d{2}$/';
$from=preg_match($valid,$from)?$from:date('Y-m-01');$to=preg_match($valid,$to)?$to:date('Y-m-d');$asAt=preg_match($valid,$asAt)?$asAt:$to;
if($from>$to){[$from,$to]=[$to,$from];}
$ready=(bool)$conn->query("SHOW TABLES LIKE 'journal_entries'")->fetchColumn()&&(bool)$conn->query("SHOW TABLES LIKE 'journal_lines'")->fetchColumn()&&(bool)$conn->query("SHOW TABLES LIKE 'accounts'")->fetchColumn();
$incomeRows=[];$expenseRows=[];$assetRows=[];$liabilityRows=[];$equityRows=[];$cashRows=[];$netIncome=0.0;$assetTotal=0.0;$liabilityTotal=0.0;$equityTotal=0.0;$difference=0.0;
if($ready){
 $periodQ=$conn->prepare("SELECT a.id,a.account_code,a.account_name,a.account_type,COALESCE(x.debit,0) debit,COALESCE(x.credit,0) credit FROM accounts a LEFT JOIN (SELECT l.account_id,SUM(l.debit) debit,SUM(l.credit) credit FROM journal_lines l JOIN journal_entries j ON j.id=l.journal_entry_id WHERE j.status='Posted' AND j.journal_date BETWEEN ? AND ? GROUP BY l.account_id) x ON x.account_id=a.id WHERE a.status='Active' AND a.account_type IN('Income','Expense') ORDER BY a.account_code");
 $periodQ->execute([$from,$to]);foreach($periodQ->fetchAll(PDO::FETCH_ASSOC) as $r){$balance=$r['account_type']==='Income'?(float)$r['credit']-(float)$r['debit']:(float)$r['debit']-(float)$r['credit'];$r['balance']=round($balance,2);if($r['account_type']==='Income'){$incomeRows[]=$r;}else{$expenseRows[]=$r;}}
 $incomeTotal=array_sum(array_column($incomeRows,'balance'));$expenseTotal=array_sum(array_column($expenseRows,'balance'));$netIncome=round($incomeTotal-$expenseTotal,2);
 $balanceQ=$conn->prepare("SELECT a.id,a.account_code,a.account_name,a.account_type,COALESCE(x.debit,0) debit,COALESCE(x.credit,0) credit FROM accounts a LEFT JOIN (SELECT l.account_id,SUM(l.debit) debit,SUM(l.credit) credit FROM journal_lines l JOIN journal_entries j ON j.id=l.journal_entry_id WHERE j.status='Posted' AND j.journal_date<=? GROUP BY l.account_id) x ON x.account_id=a.id WHERE a.status='Active' AND a.account_type IN('Asset','Liability','Equity') ORDER BY a.account_code");
 $balanceQ->execute([$asAt]);foreach($balanceQ->fetchAll(PDO::FETCH_ASSOC) as $r){$r['balance']=$r['account_type']==='Asset'?round((float)$r['debit']-(float)$r['credit'],2):round((float)$r['credit']-(float)$r['debit'],2);if(abs($r['balance'])<0.005)continue;if($r['account_type']==='Asset'){$assetRows[]=$r;$assetTotal+=$r['balance'];}elseif($r['account_type']==='Liability'){$liabilityRows[]=$r;$liabilityTotal+=$r['balance'];}else{$equityRows[]=$r;$equityTotal+=$r['balance'];}}
 $profitToDate=$conn->prepare("SELECT COALESCE(SUM(CASE WHEN a.account_type='Income' THEN l.credit-l.debit ELSE l.debit-l.credit END),0) FROM accounts a JOIN journal_lines l ON l.account_id=a.id JOIN journal_entries j ON j.id=l.journal_entry_id WHERE a.account_type IN('Income','Expense') AND j.status='Posted' AND j.journal_date<=?");
 $profitToDate->execute([$asAt]);$netIncomeToDate=round((float)$profitToDate->fetchColumn(),2);
 $equityTotal=round($equityTotal+$netIncomeToDate,2);$difference=round($assetTotal-$liabilityTotal-$equityTotal,2);
 $cashMappings=$conn->query("SELECT m.mapping_key,a.id,a.account_code,a.account_name FROM accounting_mappings m JOIN accounts a ON a.id=m.account_id WHERE m.mapping_key IN('cash_on_hand','mpesa_clearing','bank_account','other_clearing') AND a.status='Active' ORDER BY FIELD(m.mapping_key,'cash_on_hand','mpesa_clearing','bank_account','other_clearing')")->fetchAll(PDO::FETCH_ASSOC);
 $cashQ=$conn->prepare("SELECT COALESCE(SUM(CASE WHEN j.journal_date<? THEN l.debit-l.credit ELSE 0 END),0) opening,COALESCE(SUM(CASE WHEN j.journal_date BETWEEN ? AND ? AND l.debit>0 THEN l.debit ELSE 0 END),0) receipts,COALESCE(SUM(CASE WHEN j.journal_date BETWEEN ? AND ? AND l.credit>0 THEN l.credit ELSE 0 END),0) payments,COALESCE(SUM(l.debit-l.credit),0) closing FROM journal_lines l JOIN journal_entries j ON j.id=l.journal_entry_id WHERE l.account_id=? AND j.status='Posted' AND j.journal_date<=?");
 foreach($cashMappings as $cash){$cashQ->execute([$from,$from,$to,$from,$to,(int)$cash['id'],$to]);$v=$cashQ->fetch(PDO::FETCH_ASSOC)?:[];$cashRows[]=$cash+['opening'=>(float)($v['opening']??0),'receipts'=>(float)($v['receipts']??0),'payments'=>(float)($v['payments']??0),'closing'=>(float)($v['closing']??0)];}
}
$currency=(string)($conn->query("SELECT setting_value FROM settings WHERE setting_key='currency' LIMIT 1")->fetchColumn()?:'KES');
$exportRows=[['Statement','Profit and Loss'],['From',$from],['To',$to],['Revenue',array_sum(array_column($incomeRows,'balance'))],['Expenses',array_sum(array_column($expenseRows,'balance'))],['Net Profit / (Loss)',$netIncome],['Balance Sheet As At',$asAt],['Total Assets',$assetTotal],['Total Liabilities',$liabilityTotal],['Total Equity including current earnings',$equityTotal],['Balance Sheet Difference',$difference]];dibonkeReportExport('financial_statements_'.$from.'_to_'.$to,['Item','Amount'],$exportRows);
require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';
?>
<main class="content"><?php dibonkeReportPrintStyles(); ?>
<style>
.fs-panel{background:#fff;border:1px solid #e5eaf0;border-radius:12px;padding:16px;margin:14px 0}.fs-filter{display:flex;gap:10px;align-items:end;flex-wrap:wrap}.fs-filter label{display:flex;flex-direction:column;gap:5px;font-size:11px;font-weight:800}.fs-filter input{padding:9px;border:1px solid #cbd5e1;border-radius:7px}.fs-btn{background:#174a7e;color:#fff;border:0;border-radius:7px;padding:10px 14px;font-weight:800}.fs-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.fs-table{width:100%;border-collapse:collapse}.fs-table th,.fs-table td{padding:9px;border-bottom:1px solid #edf1f5;text-align:left;font-size:12px}.fs-table th{background:#f3f6fa}.num{text-align:right!important;white-space:nowrap}.fs-total{font-weight:900;color:#17324d}.muted{color:#64748b}.fs-nav{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.fs-nav a{padding:9px 12px;background:#edf2f7;border-radius:8px;text-decoration:none;color:#17324d;font-size:12px;font-weight:800}@media(max-width:700px){.fs-grid{grid-template-columns:1fr}}
</style>
<h1>Financial Statements</h1><p class="muted">Profit and Loss and Balance Sheet are generated from posted double-entry journals. Cash movement shows balances in mapped cash and bank accounts.</p>
<nav class="fs-nav"><a href="index.php">Overview</a><a href="control.php">Financial Control</a><a href="statements.php">Financial Statements</a><a href="periods.php">Period Controls</a><a href="trial_balance.php">Trial Balance</a></nav>
<?php if(!$ready):?><section class="fs-panel">Import the double-entry accounting migrations before generating statements.</section><?php else:?>
<section class="fs-panel"><form class="fs-filter"><label>P&L From<input type="date" name="from" value="<?=e($from)?>"></label><label>P&L To<input type="date" name="to" value="<?=e($to)?>"></label><label>Balance Sheet As At<input type="date" name="as_at" value="<?=e($asAt)?>"></label><button class="fs-btn">Generate Statements</button></form><?php dibonkeReportActions('financial_statements'); ?></section>
<div class="fs-grid">
<section class="fs-panel"><h2>Profit and Loss</h2><p class="muted"><?=e($from)?> to <?=e($to)?></p><h3>Income</h3><table class="fs-table"><tbody><?php foreach($incomeRows as $r):?><tr><td><?=e($r['account_code'].' — '.$r['account_name'])?></td><td class="num"><?=number_format((float)$r['balance'],2)?></td></tr><?php endforeach;?><?php if(!$incomeRows):?><tr><td colspan="2" class="muted">No posted income activity.</td></tr><?php endif;?><tr><th>Total Income</th><th class="num"><?=number_format(array_sum(array_column($incomeRows,'balance')),2)?></th></tr></tbody></table><h3 style="margin-top:16px">Expenses</h3><table class="fs-table"><tbody><?php foreach($expenseRows as $r):?><tr><td><?=e($r['account_code'].' — '.$r['account_name'])?></td><td class="num"><?=number_format((float)$r['balance'],2)?></td></tr><?php endforeach;?><?php if(!$expenseRows):?><tr><td colspan="2" class="muted">No posted expense activity.</td></tr><?php endif;?><tr><th>Total Expenses</th><th class="num"><?=number_format(array_sum(array_column($expenseRows,'balance')),2)?></th></tr><tr><th>Net Profit / (Loss)</th><th class="num fs-total"><?=number_format($netIncome,2)?></th></tr></tbody></table></section>
<section class="fs-panel"><h2>Balance Sheet</h2><p class="muted">As at <?=e($asAt)?></p><h3>Assets</h3><table class="fs-table"><tbody><?php foreach($assetRows as $r):?><tr><td><?=e($r['account_code'].' — '.$r['account_name'])?></td><td class="num"><?=number_format((float)$r['balance'],2)?></td></tr><?php endforeach;?><tr><th>Total Assets</th><th class="num"><?=number_format($assetTotal,2)?></th></tr></tbody></table><h3 style="margin-top:14px">Liabilities</h3><table class="fs-table"><tbody><?php foreach($liabilityRows as $r):?><tr><td><?=e($r['account_code'].' — '.$r['account_name'])?></td><td class="num"><?=number_format((float)$r['balance'],2)?></td></tr><?php endforeach;?><tr><th>Total Liabilities</th><th class="num"><?=number_format($liabilityTotal,2)?></th></tr></tbody></table><h3 style="margin-top:14px">Equity</h3><table class="fs-table"><tbody><?php foreach($equityRows as $r):?><tr><td><?=e($r['account_code'].' — '.$r['account_name'])?></td><td class="num"><?=number_format((float)$r['balance'],2)?></td></tr><?php endforeach;?><tr><td>Current earnings to date</td><td class="num"><?=number_format($netIncomeToDate,2)?></td></tr><tr><th>Total Equity</th><th class="num"><?=number_format($equityTotal,2)?></th></tr><tr><th>Balance Sheet Difference</th><th class="num"><?=number_format($difference,2)?></th></tr></tbody></table></section>
</div>
<section class="fs-panel"><h2>Cash and Bank Movement</h2><p class="muted">Movement in mapped cash, M-PESA clearing, bank and other clearing accounts. This is a management cash movement view, not a certified indirect cash-flow statement.</p><div style="overflow:auto"><table class="fs-table"><thead><tr><th>Account</th><th class="num">Opening</th><th class="num">Debits / Receipts</th><th class="num">Credits / Payments</th><th class="num">Closing</th></tr></thead><tbody><?php foreach($cashRows as $r):?><tr><td><?=e($r['account_code'].' — '.$r['account_name'])?></td><td class="num"><?=number_format($r['opening'],2)?></td><td class="num"><?=number_format($r['receipts'],2)?></td><td class="num"><?=number_format($r['payments'],2)?></td><td class="num"><?=number_format($r['closing'],2)?></td></tr><?php endforeach;?><?php if(!$cashRows):?><tr><td colspan="5" class="muted">Map cash, M-PESA and bank accounts in Posting Mappings.</td></tr><?php endif;?></tbody></table></div></section>
<?php endif;?></main><?php require_once __DIR__.'/../../includes/footer.php';?>
